B.bcf=new A.V("3. N\xc3O COMPARTILHAMENTO",null,B.dI,null,null,null,null,null,null,null,null,null,null)
B.bdW=new A.V("A Impetus Tecnologia n\xe3o vende, aluga ou compartilha seus dados pessoais com terceiros ou anunciantes para fins publicit\xe1rios sob nenhuma hip\xf3tese.",null,B.eG,null,null,null,null,null,null,null,null,null,null)
